import{_ as a,c as n,o as e,ah as l}from"./chunks/framework.BrJYEL96.js";const u=JSON.parse('{"title":"基础知识","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/css/教学/基础知识.md","filePath":"frontend/css/教学/基础知识.md","lastUpdated":1792062939000}'),o={name:"frontend/css/教学/基础知识.md"};function p(r,s,t,c,i,d){return e(),n("div",null,s[0]||(s[0]=[l(`<h1 id="基础知识" tabindex="-1">基础知识 <a class="header-anchor" href="#基础知识" aria-label="Permalink to &quot;基础知识&quot;">​</a></h1><h2 id="基础知识-1" tabindex="-1">基础知识 <a class="header-anchor" href="#基础知识-1" aria-label="Permalink to &quot;基础知识&quot;">​</a></h2><p>因为<code>CSS</code> 主要是对页面元素的美化，所以需要先学习 <code>HTML</code>相关课程。</p><p>大部分 HTML 元素都有系统提供的样式，但有以下问题</p><ul><li>不同浏览器显示样式不一致</li><li>样式过于简单，显示效果不美观</li><li>很难按照设计稿完全呈现显示效果</li></ul><h2 id="样式声明" tabindex="-1">样式声明 <a class="header-anchor" href="#样式声明" aria-label="Permalink to &quot;样式声明&quot;">​</a></h2><p>可以通过多种方式定义样式表。</p><h3 id="外部样式" tabindex="-1">外部样式 <a class="header-anchor" href="#外部样式" aria-label="Permalink to &quot;外部样式&quot;">​</a></h3><p>使用 <code>link</code> 标签引入外部样式文件，需要注意以下几点。</p><ul><li>link 标签放在 <code>head</code> 标签内部</li><li>样式文件要以 <code>.css</code> 为扩展名</li><li>一个页面往往需要引入多个样式文件</li></ul><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td>rel</td><td>定义当前文档与被链接文档之间的关系</td></tr><tr><td>href</td><td>外部样式文件</td></tr><tr><td>type</td><td>文档类型</td></tr></tbody></table><blockquote><p>link 还有其他属性会在其他章节单独讲解</p></blockquote><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">link</span><span style="color:#D19A66;"> rel</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;stylesheet&quot;</span><span style="color:#D19A66;"> href</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;yuxian.css&quot;</span><span style="color:#D19A66;"> type</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;text/css&quot;</span><span style="color:#ABB2BF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="嵌入样式" tabindex="-1">嵌入样式 <a class="header-anchor" href="#嵌入样式" aria-label="Permalink to &quot;嵌入样式&quot;">​</a></h3><p>使用 <code>style</code> 标签可以在文档内部定义样式规则。</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">style</span><span style="color:#ABB2BF;">&gt;</span></span>
<span class="line"><span style="color:#E06C75;">	body</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#ABB2BF;">		background: </span><span style="color:#D19A66;">red</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">	}</span></span>
<span class="line"><span style="color:#ABB2BF;">&lt;/</span><span style="color:#E06C75;">style</span><span style="color:#ABB2BF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="内联样式" tabindex="-1">内联样式 <a class="header-anchor" href="#内联样式" aria-label="Permalink to &quot;内联样式&quot;">​</a></h3><p>可以为某个标签单独设置样式。</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">h1</span><span style="color:#D19A66;"> style</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;color:green;&quot;</span><span style="color:#ABB2BF;">&gt;yuxian.com&lt;/</span><span style="color:#E06C75;">h1</span><span style="color:#ABB2BF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="导入样式" tabindex="-1">导入样式 <a class="header-anchor" href="#导入样式" aria-label="Permalink to &quot;导入样式&quot;">​</a></h3><p>使用 <code>@import</code> 可以在原样式规则中导入其他样式表，可以在外部样式、<code>style</code>标签中使用。</p><p>可以使用以下两种方式导入</p><div class="language-css line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#C678DD;">@import</span><span style="color:#98C379;"> &quot;hd.css&quot;</span></span>
<span class="line"><span style="color:#ABB2BF;">@import url(&quot;hd.css&quot;)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>导入样式要放在样式规则前面定义。</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">style</span><span style="color:#ABB2BF;">&gt;</span></span>
<span class="line"><span style="color:#C678DD;">	@import</span><span style="color:#56B6C2;"> url</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;hdcms.css&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#E06C75;">	body</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#ABB2BF;">		background: </span><span style="color:#D19A66;">red</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">	}</span></span>
<span class="line"><span style="color:#ABB2BF;">&lt;/style1&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="其他细节" tabindex="-1">其他细节 <a class="header-anchor" href="#其他细节" aria-label="Permalink to &quot;其他细节&quot;">​</a></h2><h3 id="空白" tabindex="-1">空白 <a class="header-anchor" href="#空白" aria-label="Permalink to &quot;空白&quot;">​</a></h3><p>在样式规则中可以随意使用空白，空白只是看不见但同样占用空间，所以可以结合其他工具如 <code>webpack</code> 等将<code>css</code> 压缩为一行。</p><h3 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h3><p>注释是对定义样式规则的说明，便于后期维护理解。</p><div class="language-css line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#C678DD;">...</span></span>
<span class="line"><span style="color:#E06C75;">body</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">	/* 这是注释的使用 */</span></span>
<span class="line"><span style="color:#ABB2BF;">	background: </span><span style="color:#D19A66;">red</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"><span style="color:#C678DD;">...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="错误" tabindex="-1">错误 <a class="header-anchor" href="#错误" aria-label="Permalink to &quot;错误&quot;">​</a></h3><p>样式规则如果存在错误，解析器会选择忽略，并不会影响其他样式规则。</p><p>以下代码的<code>yuxian:red</code> 是无效样式但不影响后面的 <code>font-size:100px;</code> 规则使用。</p><div class="language-css line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#E06C75;">h1</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#ABB2BF;">    yuxian: </span><span style="color:#D19A66;">red</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    font-size: </span><span style="color:#D19A66;">100</span><span style="color:#E06C75;">px</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="初始样式" tabindex="-1">初始样式 <a class="header-anchor" href="#初始样式" aria-label="Permalink to &quot;初始样式&quot;">​</a></h2><p>有些标签默认含有内外边距，且不同浏览器大小也不一样。为了统一我们可以重置标签的 CSS 默认样式。</p><p>最简单的方式就是使用插件<a href="https://meyerweb.com/eric/tools/css/reset/" target="_blank" rel="noreferrer">css-reset</a>完成，你也可以在 vscode 等编辑器中定义代码片段。</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-dark-pro vp-code" style="background-color:#282c34;color:#abb2bf;" tabindex="0"><code><span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">link</span><span style="color:#D19A66;"> rel</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;stylesheet&quot;</span><span style="color:#D19A66;"> href</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;https://cdnjs.cloudflare.com/ajax/libs/meyer-reset/2.0/reset.min.css&quot;</span><span style="color:#ABB2BF;"> /&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,39)]))}const B=a(o,[["render",p]]);export{u as __pageData,B as default};
